import { Fredoka, Gaegu } from "next/font/google";

/**
 * MARSH 마쉬 — a squishy marshmallow confectionery. The voice is pillowy,
 * candy-soft, rounded. Fredoka — a soft rounded sans with a friendly bounce,
 * perfect for the marshmallow wordmark and headings. Gaegu (400/700) — a round
 * handwritten Hangul that keeps the squishy, candy-soft voice.
 *
 * styles.css consumes these as var(--font-fredoka) / var(--font-gaegu);
 * page.tsx applies the .variable classes on the entry root.
 */
export const fredoka = Fredoka({
  weight: ["400", "500", "600", "700"],
  subsets: ["latin"],
  variable: "--font-fredoka",
  display: "swap",
});

export const gaegu = Gaegu({
  weight: ["400", "700"],
  subsets: ["latin"],
  variable: "--font-gaegu",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { fredoka, gaegu } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "MARSH";

/**
 * MARSH 마쉬 — a squishy marshmallow confectionery. The signature is a
 * DRAGGABLE marshmallow: pointer-down grabs it, drag moves it with inertia
 * (the blob lags and stretches toward the cursor), and on release it springs
 * back to rest with overshoot (`cubic-bezier(0.34, 1.8, 0.5, 1)`). It squashes
 * — scaling wider/shorter — the further it's dragged, then puffs back.
 *
 * The wordmark "MARSH" is white fill with a thick pink outline and soft pink
 * drop shadows. `.marsh-js` is added on mount so the no-JS markup is the
 * finished page; under reduced motion the marshmallow sits at rest (no drag).
 */
export default function MarshPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const mallRef = useRef<HTMLDivElement | null>(null);
  const padRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("marsh-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "marsh" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Drag physics — grab the marshmallow, drag with inertia, spring back on
  // release with overshoot. Squash factor grows with distance from rest.
  useEffect(() => {
    const mall = mallRef.current;
    const pad = padRef.current;
    if (!mall || !pad || reduced) return;

    const EPS = 1;
    let dragging = false;
    let px = 0; // pointer pos
    let py = 0;
    let restX = 0; // rest origin (center of pad)
    let restY = 0;
    let x = 0; // current offset from rest
    let y = 0;
    let vx = 0; // velocity for inertia
    let vy = 0;
    let raf = 0;

    const computeRest = () => {
      const r = pad.getBoundingClientRect();
      restX = Math.max(EPS, r.width) / 2;
      restY = Math.max(EPS, r.height) / 2;
    };
    computeRest();

    const render = () => {
      if (!Number.isFinite(x) || !Number.isFinite(y)) return;
      // Squash: the further from rest, the more it stretches along the drag
      // axis (dist) and flattens across it. Cap so it never inverts.
      const dist = Math.sqrt(x * x + y * y);
      const stretch = Math.min(0.22, dist / 320);
      const sx = 1 + stretch;
      const sy = 1 - stretch * 0.7;
      mall.style.setProperty("--mh-x", `${x.toFixed(1)}px`);
      mall.style.setProperty("--mh-y", `${y.toFixed(1)}px`);
      mall.style.setProperty("--mh-sx", sx.toFixed(3));
      mall.style.setProperty("--mh-sy", sy.toFixed(3));
      mall.style.setProperty("--mh-drag", dragging ? "1" : "0");
    };

    const onDown = (ev: PointerEvent) => {
      dragging = true;
      mall.setPointerCapture?.(ev.pointerId);
      const r = pad.getBoundingClientRect();
      px = ev.clientX - r.left;
      py = ev.clientY - r.top;
      vx = 0;
      vy = 0;
      if (!raf) raf = requestAnimationFrame(loop);
    };
    const onMove = (ev: PointerEvent) => {
      if (!dragging) return;
      const r = pad.getBoundingClientRect();
      if (r.width < EPS) return;
      const npx = ev.clientX - r.left;
      const npy = ev.clientY - r.top;
      if (!Number.isFinite(npx) || !Number.isFinite(npy)) return;
      // Inertia: target follows pointer, velocity = last delta.
      vx = npx - px;
      vy = npy - py;
      px = npx;
      py = npy;
      if (!raf) raf = requestAnimationFrame(loop);
    };
    const onUp = () => {
      dragging = false;
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const loop = () => {
      if (dragging) {
        // Spring toward the pointer with a little give (inertia lag).
        const tx = px - restX;
        const ty = py - restY;
        x += (tx - x) * 0.28;
        y += (ty - y) * 0.28;
        raf = requestAnimationFrame(loop);
      } else {
        // Release: fly out on velocity, then spring back to 0 with overshoot.
        x += vx;
        y += vy;
        vx *= 0.86;
        vy *= 0.86;
        // Spring stiffness / damping toward rest.
        x += (0 - x) * 0.12;
        y += (0 - y) * 0.12;
        const near = Math.abs(x) < 0.4 && Math.abs(y) < 0.4 && Math.abs(vx) < 0.4 && Math.abs(vy) < 0.4;
        if (near) {
          x = 0; y = 0; vx = 0; vy = 0;
          raf = 0;
        } else {
          raf = requestAnimationFrame(loop);
        }
      }
      render();
    };

    mall.style.touchAction = "none";
    mall.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);

    const ro = new ResizeObserver(computeRest);
    ro.observe(pad);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      mall.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
      ro.disconnect();
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${fredoka.variable} ${gaegu.variable} marsh-root`}>
      <div className="marsh-bg" aria-hidden="true" />
      <div ref={revealRef} className="marsh-doc">
        <header className="marsh-hero">
          <p className="marsh-kicker">
            <span lang="ko">마시멜로 제과점</span> · SQUISHY MARSHMALLOW · 2026
          </p>
          <h1 className="marsh-title" aria-label={TITLE}>
            <span className="marsh-outline" aria-hidden="true">
              {TITLE.split("").map((ch, i) => (
                <span key={i} className="marsh-glyph" style={{ "--mh-i": i } as CSSProperties}>
                  {ch}
                </span>
              ))}
            </span>
          </h1>
          <p className="marsh-title__ko" lang="ko">마쉬</p>
          <p className="marsh-sub">
            <span lang="ko">말랑한 마시멜로.</span> Squishy marshmallow.
          </p>
          <p className="marsh-hint" lang="ko">마시멜로를 끌어서 움직여 보세요 — 놓으면 말랑하게 되튕깁니다.</p>

          <div ref={padRef} className="marsh-pad">
            <div ref={mallRef} className="marsh-mallow" role="button" tabIndex={0} aria-label="드래그 가능한 마시멜로">
              <span className="marsh-mallow__top" aria-hidden="true" />
            </div>
          </div>
        </header>

        <main>
          <section className="marsh-grid">
            {[
              { ko: "바닐라 구름", en: "Vanilla cloud", n: "01" },
              { ko: "딸기 폭신", en: "Strawberry puff", n: "02" },
              { ko: "초코 말랑", en: "Choco squish", n: "03" },
            ].map((c, i) => (
              <article
                key={i}
                className="marsh-card marsh-press"
                data-reveal
                style={{ "--mh-d": i * 90 } as CSSProperties}
              >
                <span className="marsh-card__n">{c.n}</span>
                <span className="marsh-card__en">{c.en}</span>
                <span className="marsh-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>

          <section className="marsh-lead" data-reveal>
            <p className="marsh-lead__p">
              <span lang="ko">
                우리는 구움이 아니라 폭신함을 만든다. 손에 닿으면 찌릿하고,
                놓으면 도로 부풀어 오르는 — 말랑한 한 입.
              </span>{" "}
              We don't bake — we puff. Soft to the touch, it yields when pressed
              and puffs back when let go: one squishy bite.
            </p>
          </section>
        </main>

        <footer className="marsh-foot">
          <span>MARSH · 2026</span>
          <span lang="ko">마쉬 — 서울</span>
        </footer>
      </div>
    </div>
  );
}

.marsh-root {
  --mh-bg: #fff0f5;
  --mh-paper: #fff7fb;
  --mh-text: #6a3a52;
  --mh-mute: #b08aa0;
  --mh-pink: #ff7aa8;
  --mh-pink-deep: #e85a8a;
  --mh-pink-soft: #ffc6dc;
  --mh-font-display: var(--font-fredoka), "Fredoka", system-ui, sans-serif;
  --mh-font-kr: var(--font-gaegu), "Gaegu", sans-serif;
  --mh-ease: cubic-bezier(0.34, 1.8, 0.5, 1);

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(60% 50% at 20% 16%, rgba(255, 154, 196, 0.30), transparent 70%),
    radial-gradient(50% 46% at 84% 20%, rgba(255, 198, 220, 0.40), transparent 72%),
    radial-gradient(70% 60% at 50% 108%, rgba(255, 122, 168, 0.18), transparent 72%),
    var(--mh-bg);
  color: var(--mh-text);
  font-family: var(--mh-font-kr);
  font-weight: 400;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
.marsh-root ::selection { background: var(--mh-pink); color: #fff; }

.marsh-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
  background-image:
    radial-gradient(rgba(232, 90, 138, 0.06) 1px, transparent 1px);
  background-size: 26px 26px;
}

.marsh-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Hero ---- */
.marsh-hero {
  min-height: 86vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) 0 2rem;
}
.marsh-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--mh-font-display);
  font-size: clamp(0.74rem, 1.1vw, 0.9rem);
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--mh-pink-deep);
}
.marsh-title {
  margin: 0;
  font-family: var(--mh-font-display);
  font-weight: 700;
  font-size: clamp(3rem, 14vw, 11rem);
  line-height: 0.88;
  letter-spacing: -0.01em;
}
/* Marshmallow wordmark: white fill, thick pink outline, soft pink drop shadows —
   pillowy candy lettering. */
.marsh-outline {
  display: inline-block;
  color: #fff;
  -webkit-text-stroke: 3px var(--mh-pink);
  paint-order: stroke fill;
  text-shadow:
    0 3px 0 var(--mh-pink-soft),
    0 6px 1px var(--mh-pink),
    0 10px 14px rgba(232, 90, 138, 0.45),
    0 16px 26px rgba(232, 90, 138, 0.3);
  filter: drop-shadow(0 2px 1px rgba(255, 255, 255, 0.9));
}
.marsh-glyph { display: inline-block; }
.marsh-title__ko {
  margin: 0.8rem 0 0;
  font-family: var(--mh-font-kr);
  font-weight: 700;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.3em;
  color: var(--mh-pink-deep);
}
.marsh-sub {
  margin: 1.6rem 0 0.4rem;
  font-family: var(--mh-font-display);
  font-size: clamp(1.1rem, 2vw, 1.5rem);
  font-weight: 600;
}
.marsh-sub span[lang="ko"] { color: var(--mh-mute); margin-right: 0.5rem; }
.marsh-hint {
  margin: 0 0 2rem;
  font-size: 0.86rem;
  color: var(--mh-pink-deep);
}

/* ---- The draggable marshmallow ---- */
.marsh-pad {
  position: relative;
  width: 100%;
  height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.marsh-mallow {
  --mh-x: 0px;
  --mh-y: 0px;
  --mh-sx: 1;
  --mh-sy: 1;
  --mh-drag: 0;
  position: relative;
  width: 150px;
  height: 150px;
  border-radius: 48% 52% 50% 50% / 52% 50% 50% 48%;
  background:
    radial-gradient(60% 50% at 40% 30%, #ffffff 0%, #fff6fb 60%, #ffe3ef 100%);
  transform: translate3d(var(--mh-x), var(--mh-y), 0) scale(var(--mh-sx), var(--mh-sy));
  /* Springy transition ONLY when not dragging — when dragging we drive the
     transform per-frame, so transition would fight the rAF. */
  transition: transform 520ms var(--mh-ease);
  cursor: grab;
  box-shadow:
    inset 0 6px 10px rgba(255, 255, 255, 0.9),
    inset 0 -14px 22px rgba(255, 154, 196, 0.4),
    0 18px 30px -10px rgba(232, 90, 138, 0.4),
    0 30px 50px -16px rgba(232, 90, 138, 0.3);
}
/* While dragging, disable the spring transition so per-frame values are crisp. */
.marsh-mallow[style*="--mh-drag"] { transition: none; }
.marsh-mallow:active { cursor: grabbing; }
.marsh-mallow__top {
  position: absolute;
  left: 18%; right: 18%; top: 10%;
  height: 32%;
  border-radius: 50%;
  background: radial-gradient(60% 80% at 50% 40%, rgba(255, 200, 220, 0.85), transparent 70%);
  pointer-events: none;
}
.marsh-mallow:focus-visible { outline: 2px solid var(--mh-pink); outline-offset: 6px; }

/* ---- Cards ---- */
.marsh-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(1rem, 1.8vw, 1.5rem);
  padding: clamp(1rem, 3vw, 2rem) 0;
}
.marsh-card {
  position: relative;
  padding: clamp(1.4rem, 2.6vw, 2rem);
  border-radius: 28px;
  min-height: 170px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  justify-content: flex-end;
  background: linear-gradient(160deg, #ffffff, var(--mh-pink-soft));
  color: var(--mh-text);
  box-shadow:
    inset 0 2px 3px rgba(255, 255, 255, 0.9),
    inset 0 -8px 14px rgba(232, 90, 138, 0.22),
    0 14px 22px -10px rgba(232, 90, 138, 0.3),
    0 26px 40px -16px rgba(232, 90, 138, 0.25);
  cursor: pointer;
  border: none;
  text-align: left;
  transition: transform 220ms var(--mh-ease), box-shadow 220ms ease;
}
.marsh-press:active {
  transform: scale(0.96);
  box-shadow:
    inset 0 2px 3px rgba(255, 255, 255, 0.7),
    inset 0 -4px 10px rgba(232, 90, 138, 0.28),
    0 6px 12px -6px rgba(232, 90, 138, 0.4);
}
.marsh-card__n { font-family: var(--mh-font-display); font-weight: 700; font-size: 0.8rem; color: var(--mh-pink-deep); letter-spacing: 0.2em; }
.marsh-card__en { font-family: var(--mh-font-display); font-weight: 700; font-size: 1.25rem; }
.marsh-card__ko { font-size: 0.9rem; color: var(--mh-mute); }

.marsh-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(232, 90, 138, 0.2);
}
.marsh-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--mh-font-display);
  font-weight: 500;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
}
.marsh-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--mh-font-kr);
  color: var(--mh-mute);
  font-size: 0.74em;
  margin-bottom: 0.6em;
}

.marsh-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(232, 90, 138, 0.2);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--mh-mute);
  font-family: var(--mh-font-display);
  font-weight: 600;
}

/* ---- Reveal gating ---- */
.marsh-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--mh-ease), transform 800ms var(--mh-ease);
  transition-delay: calc(var(--mh-d, 0) * 1ms);
}
.marsh-js [data-reveal].is-visible { opacity: 1; transform: none; }
.marsh-js .marsh-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--mh-ease), transform 700ms var(--mh-ease);
  transition-delay: calc(var(--mh-i) * 70ms + 150ms);
}
.marsh-js.is-mounted .marsh-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .marsh-js [data-reveal], .marsh-js .marsh-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
  .marsh-mallow, .marsh-card { transition: none !important; }
}
.marsh-root :focus-visible { outline: 2px solid var(--mh-pink); outline-offset: 3px; }
